// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/settings", wrapper.GetClubSettings)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/settings/sections/{section}", wrapper.SaveClubSettings)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/settings/timezone", wrapper.SaveClubTimezone)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/settings/languages", wrapper.GetClubLanguages)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/settings/language", wrapper.SaveClubLanguage)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/settings/agent-pin", wrapper.SaveAgentPin)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/settings/agent-staff-time", wrapper.SaveAgentStaffTime)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/settings/logo", wrapper.DeleteClubLogo)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/settings/logo", wrapper.UploadClubLogo)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/settings/signin-image", wrapper.DeleteSigninImage)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/settings/signin-image", wrapper.UploadSigninImage)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/settings/location", wrapper.SaveClubLocation)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/settings/reseller", wrapper.GetClubReseller)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/settings/reseller", wrapper.AttachClubReseller)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/settings/profile", wrapper.GetClubProfile)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/settings/profile", wrapper.SaveClubProfile)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/settings/profile/photos", wrapper.UploadClubPhotos)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/settings/profile/photos/{photo}", wrapper.DeleteClubPhoto)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/settings/profile/photos/{photo}/cover", wrapper.SetClubPhotoCover)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/settings/profile/zones/{zone}", wrapper.SaveClubZoneProfile)
	})

	return r
}

